style.css:
@-moz-document domain("open.spotify.com") {
:root{
    --baby: #eaf8ff;   /* ultra light baby blue */
    --off:  #f8f8f2;   /* off-white */
    --off2: #fdfdf9;   /* off-white (alt) */
    --pastel:#6aa9ff;  /* pastel light blue (text) */
    --hover:#b3e5fc;   /* hover pastel */
  }

  /* Base / page */
  html, body, #main, .Root__top-container, .Root__now-playing-bar-container {
    background-color: var(--baby) !important;
    color: var(--pastel) !important;
  }

  /* Sidebar */
  nav[aria-label="Main"], .Root__nav-bar, .Root__left-column {
    background-color: var(--off) !important;
    color: var(--pastel) !important;
  }

  /* Main content panels */
  div[role="main"], .Type__Container-sc-1j7k0u9-0, .main-root {
    background-color: var(--off2) !important;
    color: var(--pastel) !important;
  }

  /* Cards / tiles / album blocks */
  .main-card-card, .card, [class*="Card"], .cover-art, .react-contextmenu-wrapper {
    background-color: var(--baby) !important;
    color: var(--pastel) !important;
    border-radius: 10px !important;
  }

  /* Text & links */
  a, p, span, li, h1, h2, h3, h4, h5, h6 {
    color: var(--pastel) !important;
  }

  /* Buttons & controls */
  button, .control-button, .spoticon, .btn {
    background-color: var(--off2) !important;
    border: 1px solid var(--hover) !important;
    color: var(--pastel) !important;
    border-radius: 8px !important;
  }

  button:hover, .btn:hover, .control-button:hover {
    background-color: var(--hover) !important;
    color: var(--off) !important; /* off-white text on hover */
  }

  /* Now playing bar (soft gradient) */
  .Root__now-playing-bar, .now-playing-bar, .Root__now-playing-bar-container {
    background: linear-gradient(90deg, var(--off) 0%, var(--baby) 100%) !important;
    color: var(--pastel) !important;
  }

  /* Overlays / modals: remove dark backgrounds */
  [class*="overlay"], [class*="Overlay"], [class*="background"], .modal-backdrop {
    background-color: transparent !important;
    color: var(--pastel) !important;
  }

  /* Images */
  img, .cover-art-image, .albumArt {
    opacity: 1 !important;
    filter: none !important;
  }

  /* Inputs / search */
  input, textarea, .searchBox, .searchInput {
    background-color: var(--off2) !important;
    color: var(--pastel) !important;
    border: 1px solid var(--hover) !important;
  }

  /* Scrollbars (soft) */
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-thumb { background-color: var(--hover); border-radius: 6px; }
  ::-webkit-scrollbar-track { background-color: var(--off2); }

  /* small fallback */
  * { background-image: none !important; }
}
